INSERT INTO `pendidikans` VALUES (1,1,'1','tks-ar-rabwah','TKS Ar-Rabwah','Profil SingkatTaman Kanak-Kanak Islam Ar-Rabwah merupakan lembaga pendidikan formal tingkat pra-sekolah yang bernaung di bawah Pesantren Islam Ar-Rabwah. Sekolah ini berfokus pada pembentukan karakter Islami sejak usia dini, dengan pembelajaran yang menyenangkan dan berbasis nilai Al-Qur’an.Status SekolahJenjang: Taman Kanak-Kanak (TK)Kategori: FormalSistem: Non Boarding (pulang setiap hari)Terdaftar di Dinas Pendidikan Kabupaten Aceh Besar, Nomor: 137 Tahun 2019Sejarah SingkatTKS Ar-Rabwah berdiri sebagai bagian dari pengembangan pendidikan dasar di lingkungan pesantren. Tujuannya memberikan fondasi keimanan, adab, dan kemandirian sejak usia dini. Anak-anak dibimbing oleh guru berpengalaman yang menanamkan kecintaan terhadap Al-Qur’an dan nilai-nilai Islam sejak awal.VisiMenumbuhkan generasi cerdas, berakhlak, dan mencintai Al-Qur’an sejak usia dini.MisiMengembangkan potensi anak melalui pembelajaran aktif dan islami.Membentuk karakter sopan santun, disiplin, dan gemar beribadah.Menanamkan kecintaan terhadap Al-Qur’an dan Rasulullah ﷺ.TujuanMencetak anak-anak usia dini yang berani, beradab, ceria, dan memiliki dasar aqidah yang kuat.KeunggulanPembelajaran tematik berbasis nilai IslamGuru berpengalaman dan penuh kasihKegiatan harian berbasis ibadah dan adab','<p><strong>Profil Singkat</strong></p><p class=\"ql-align-justify\">Taman Kanak-Kanak Islam Ar-Rabwah merupakan lembaga pendidikan formal tingkat pra-sekolah yang bernaung di bawah Pesantren Islam Ar-Rabwah. Sekolah ini berfokus pada pembentukan karakter Islami sejak usia dini, dengan pembelajaran yang menyenangkan dan berbasis nilai Al-Qur’an.</p><p><strong>Status Sekolah</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jenjang: Taman Kanak-Kanak (TK)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Kategori: Formal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistem: Non Boarding (pulang setiap hari)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Terdaftar di Dinas Pendidikan Kabupaten Aceh Besar, Nomor: 137 Tahun 2019</li></ol><p><strong>Sejarah Singkat</strong></p><p class=\"ql-align-justify\">TKS Ar-Rabwah berdiri sebagai bagian dari pengembangan pendidikan dasar di lingkungan pesantren. Tujuannya memberikan fondasi keimanan, adab, dan kemandirian sejak usia dini. Anak-anak dibimbing oleh guru berpengalaman yang menanamkan kecintaan terhadap Al-Qur’an dan nilai-nilai Islam sejak awal.</p><p><strong>Visi</strong></p><p>Menumbuhkan generasi cerdas, berakhlak, dan mencintai Al-Qur’an sejak usia dini.</p><p><strong>Misi</strong></p><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mengembangkan potensi anak melalui pembelajaran aktif dan islami.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Membentuk karakter sopan santun, disiplin, dan gemar beribadah.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menanamkan kecintaan terhadap Al-Qur’an dan Rasulullah ﷺ.</li></ol><p><strong>Tujuan</strong></p><p>Mencetak anak-anak usia dini yang berani, beradab, ceria, dan memiliki dasar aqidah yang kuat.</p><p><strong>Keunggulan</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pembelajaran tematik berbasis nilai Islam</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Guru berpengalaman dan penuh kasih</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Kegiatan harian berbasis ibadah dan adab</li></ol><p><br></p>','http://rabwah.test/storage/photos/1/swip1.jpg','published',0,0,NULL,NULL,'2025-11-04 15:10:43','2025-11-04 08:10:43','2025-11-04 08:10:43',NULL),(2,1,'2','sd-it-ar-rabwah','SD IT Ar-Rabwah','Profil SingkatSekolah Dasar Islam Terpadu Ar-Rabwah adalah lembaga pendidikan formal tingkat dasar di bawah naungan Pesantren Islam Ar-Rabwah. Sekolah ini berkomitmen membentuk generasi Qurani yang cerdas, berakhlak, dan terampil.Status SekolahJenjang: Sekolah Dasar (SD)Kategori: FormalSistem: Non BoardingTerdaftar di Dinas Pendidikan Kabupaten Aceh Besar, Nomor: 015.a Tahun 2021Sejarah SingkatSD IT Ar-Rabwah didirikan untuk memenuhi kebutuhan pendidikan dasar berbasis Islam terpadu di lingkungan pesantren. Pembelajaran menggabungkan kurikulum nasional dengan pendidikan Al-Qur’an, adab, dan bahasa Arab.VisiMewujudkan generasi Qurani yang berilmu, beradab, dan berdaya saing.MisiMenanamkan nilai Al-Qur’an dan Sunnah dalam setiap kegiatan belajar.Mengintegrasikan ilmu pengetahuan umum dengan nilai-nilai Islam.Membangun karakter mandiri, disiplin, dan peduli sesama.TujuanMembentuk siswa berprestasi yang berakhlakul karimah dan memiliki kecintaan kepada ilmu serta Al-Qur’an.KeunggulanTahfidz dan bahasa Arab sejak diniPembelajaran kontekstual dan kreatifLingkungan belajar kondusif dan islami','<p><strong>Profil Singkat</strong></p><p class=\"ql-align-justify\">Sekolah Dasar Islam Terpadu Ar-Rabwah adalah lembaga pendidikan formal tingkat dasar di bawah naungan Pesantren Islam Ar-Rabwah. Sekolah ini berkomitmen membentuk generasi Qurani yang cerdas, berakhlak, dan terampil.</p><p><strong>Status Sekolah</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jenjang: Sekolah Dasar (SD)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Kategori: Formal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistem: Non Boarding</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Terdaftar di Dinas Pendidikan Kabupaten Aceh Besar, Nomor: 015.a Tahun 2021</li></ol><p><strong>Sejarah Singkat</strong></p><p class=\"ql-align-justify\">SD IT Ar-Rabwah didirikan untuk memenuhi kebutuhan pendidikan dasar berbasis Islam terpadu di lingkungan pesantren. Pembelajaran menggabungkan kurikulum nasional dengan pendidikan Al-Qur’an, adab, dan bahasa Arab.</p><p><strong>Visi</strong></p><p>Mewujudkan generasi Qurani yang berilmu, beradab, dan berdaya saing.</p><p><strong>Misi</strong></p><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menanamkan nilai Al-Qur’an dan Sunnah dalam setiap kegiatan belajar.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mengintegrasikan ilmu pengetahuan umum dengan nilai-nilai Islam.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Membangun karakter mandiri, disiplin, dan peduli sesama.</li></ol><p><strong>Tujuan</strong></p><p>Membentuk siswa berprestasi yang berakhlakul karimah dan memiliki kecintaan kepada ilmu serta Al-Qur’an.</p><p><strong>Keunggulan</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Tahfidz dan bahasa Arab sejak dini</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pembelajaran kontekstual dan kreatif</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Lingkungan belajar kondusif dan islami</li></ol><p><br></p>','http://rabwah.test/storage/photos/1/swip1.jpg','published',0,0,NULL,NULL,'2025-11-04 15:11:41','2025-11-04 08:11:41','2025-11-04 08:11:41',NULL),(3,1,'3','smp-it-ar-rabwah','SMP IT Ar-Rabwah','Profil SingkatSMP Islam Terpadu Ar-Rabwah adalah lembaga pendidikan formal tingkat menengah pertama yang mengintegrasikan ilmu umum, ilmu agama, dan pembentukan karakter islami melalui sistem boarding (asrama).Status SekolahJenjang: Sekolah Menengah Pertama (SMP)Kategori: FormalSistem: Boarding (berasrama)Terdaftar di Dinas Pendidikan Kabupaten Aceh Besar, Nomor: 421/SMP-246/2008 (Terakreditasi)Sejarah SingkatSMP IT Ar-Rabwah menjadi tonggak penting dalam pembinaan remaja muslim. Melalui sistem boarding, santri dibimbing agar mandiri, disiplin, dan berakhlak mulia, sekaligus berprestasi di bidang akademik.VisiMembentuk generasi Qurani, cerdas, berdaya saing, dan berakhlak mulia.MisiMenyelenggarakan pendidikan terpadu antara ilmu umum dan ilmu agama.Mendorong santri untuk menghafal Al-Qur’an dan memahami maknanya.Membina kedisiplinan dan kemandirian melalui kehidupan asrama.TujuanMelahirkan pelajar muslim yang siap melanjutkan pendidikan ke jenjang lebih tinggi dengan karakter islami dan mental tangguh.KeunggulanSistem boarding mendukung pembinaan karakterProgram tahfidz intensifPembelajaran bilingual (Arab–Inggris)','<p><strong>Profil Singkat</strong></p><p class=\"ql-align-justify\">SMP Islam Terpadu Ar-Rabwah adalah lembaga pendidikan formal tingkat menengah pertama yang mengintegrasikan ilmu umum, ilmu agama, dan pembentukan karakter islami melalui sistem boarding (asrama).</p><p><strong>Status Sekolah</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jenjang: Sekolah Menengah Pertama (SMP)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Kategori: Formal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistem: Boarding (berasrama)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Terdaftar di Dinas Pendidikan Kabupaten Aceh Besar, Nomor: 421/SMP-246/2008 (Terakreditasi)</li></ol><p><strong>Sejarah Singkat</strong></p><p class=\"ql-align-justify\">SMP IT Ar-Rabwah menjadi tonggak penting dalam pembinaan remaja muslim. Melalui sistem boarding, santri dibimbing agar mandiri, disiplin, dan berakhlak mulia, sekaligus berprestasi di bidang akademik.</p><p><strong>Visi</strong></p><p>Membentuk generasi Qurani, cerdas, berdaya saing, dan berakhlak mulia.</p><p><strong>Misi</strong></p><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menyelenggarakan pendidikan terpadu antara ilmu umum dan ilmu agama.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mendorong santri untuk menghafal Al-Qur’an dan memahami maknanya.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Membina kedisiplinan dan kemandirian melalui kehidupan asrama.</li></ol><p><strong>Tujuan</strong></p><p>Melahirkan pelajar muslim yang siap melanjutkan pendidikan ke jenjang lebih tinggi dengan karakter islami dan mental tangguh.</p><p><strong>Keunggulan</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistem boarding mendukung pembinaan karakter</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Program tahfidz intensif</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pembelajaran bilingual (Arab–Inggris)</li></ol><p><br></p>','http://rabwah.test/storage/photos/1/swip1.jpg','published',0,0,NULL,NULL,'2025-11-04 15:12:47','2025-11-04 08:12:47','2025-11-04 08:12:47',NULL),(4,1,'4','mas-ar-rabwah','MAS Ar-Rabwah','Profil SingkatMadrasah Aliyah Swasta Ar-Rabwah adalah lembaga pendidikan formal setara SMA yang memadukan kurikulum nasional Kemenag dengan penguatan keislaman dan pembinaan akhlak di lingkungan pesantren.Status SekolahJenjang: Madrasah Aliyah (SMA)Kategori: FormalSistem: BoardingTerdaftar di Kantor Wilayah Kementerian Agama Provinsi Aceh, Nomor: C/KW.01/MA/108/2007 (Terakreditasi)Sejarah SingkatMAS Ar-Rabwah berdiri sebagai lanjutan dari jenjang pendidikan di Pesantren Ar-Rabwah. Didesain untuk membentuk generasi intelektual yang kuat dalam ilmu, matang secara spiritual, dan siap berdakwah di masyarakat.VisiMembentuk generasi muda berilmu, beriman, dan berakhlakul karimah yang siap menjadi pemimpin masa depan.MisiMenghasilkan lulusan yang menguasai ilmu agama dan umum secara seimbang.Menumbuhkan semangat belajar, beribadah, dan beramal shaleh.Menyiapkan siswa yang siap bersaing di dunia akademik dan sosial.TujuanMelahirkan kader intelektual muslim yang siap berkontribusi dalam masyarakat dengan dasar iman dan ilmu.KeunggulanProgram tahfidz dan kajian kitabPembinaan kepemimpinan dan dakwahDisiplin dan pembinaan karakter santri','<p><strong>Profil Singkat</strong></p><p class=\"ql-align-justify\">Madrasah Aliyah Swasta Ar-Rabwah adalah lembaga pendidikan formal setara SMA yang memadukan kurikulum nasional Kemenag dengan penguatan keislaman dan pembinaan akhlak di lingkungan pesantren.</p><p><strong>Status Sekolah</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jenjang: Madrasah Aliyah (SMA)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Kategori: Formal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistem: Boarding</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Terdaftar di Kantor Wilayah Kementerian Agama Provinsi Aceh, Nomor: C/KW.01/MA/108/2007 (Terakreditasi)</li></ol><p><strong>Sejarah Singkat</strong></p><p class=\"ql-align-justify\">MAS Ar-Rabwah berdiri sebagai lanjutan dari jenjang pendidikan di Pesantren Ar-Rabwah. Didesain untuk membentuk generasi intelektual yang kuat dalam ilmu, matang secara spiritual, dan siap berdakwah di masyarakat.</p><p><strong>Visi</strong></p><p>Membentuk generasi muda berilmu, beriman, dan berakhlakul karimah yang siap menjadi pemimpin masa depan.</p><p><strong>Misi</strong></p><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menghasilkan lulusan yang menguasai ilmu agama dan umum secara seimbang.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menumbuhkan semangat belajar, beribadah, dan beramal shaleh.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menyiapkan siswa yang siap bersaing di dunia akademik dan sosial.</li></ol><p><strong>Tujuan</strong></p><p>Melahirkan kader intelektual muslim yang siap berkontribusi dalam masyarakat dengan dasar iman dan ilmu.</p><p><strong>Keunggulan</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Program tahfidz dan kajian kitab</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pembinaan kepemimpinan dan dakwah</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Disiplin dan pembinaan karakter santri</li></ol><p><br></p>','http://rabwah.test/storage/photos/1/swip1.jpg','published',0,0,NULL,NULL,'2025-11-04 15:13:48','2025-11-04 08:13:48','2025-11-04 08:14:04',NULL),(5,1,'5','tpq-ar-rabwah','TPQ Ar-Rabwah','Profil SingkatTaman Pendidikan Al-Qur’an (TPQ) Ar-Rabwah merupakan lembaga non formal yang fokus pada pendidikan dasar Al-Qur’an, adab, dan ibadah bagi anak-anak. Kegiatan dilaksanakan di lingkungan pesantren dengan sistem boarding.Status LembagaJenjang: Pendidikan Non FormalKategori: TPQ (Taman Pendidikan Al-Qur’an)Sistem: BoardingTerdaftar di Kementerian Agama Kabupaten Aceh BesarSejarah SingkatTPQ Ar-Rabwah menjadi cikal bakal tumbuhnya semangat Qurani di lingkungan pesantren. Sejak awal berdirinya, lembaga ini menjadi wadah pembinaan baca-tulis Al-Qur’an dan penanaman akhlak bagi anak-anak dari berbagai daerah.VisiMenumbuhkan generasi cinta Al-Qur’an, beradab, dan istiqamah dalam ibadah.MisiMengajarkan baca tulis Al-Qur’an sesuai kaidah tajwid.Membentuk karakter anak yang berakhlak dan gemar beribadah.Menanamkan nilai keikhlasan, disiplin, dan tanggung jawab sejak dini.TujuanMencetak generasi Qurani yang mampu membaca, menghafal, dan mengamalkan Al-Qur’an dalam kehidupan sehari-hari.KeunggulanMetode belajar interaktif dan berjenjangPengajar hafizh berpengalamanLingkungan pesantren yang mendukung pembiasaan ibadah','<p><strong>Profil Singkat</strong></p><p class=\"ql-align-justify\">Taman Pendidikan Al-Qur’an (TPQ) Ar-Rabwah merupakan lembaga non formal yang fokus pada pendidikan dasar Al-Qur’an, adab, dan ibadah bagi anak-anak. Kegiatan dilaksanakan di lingkungan pesantren dengan sistem boarding.</p><p><strong>Status Lembaga</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Jenjang: Pendidikan Non Formal</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Kategori: TPQ (Taman Pendidikan Al-Qur’an)</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Sistem: Boarding</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Terdaftar di Kementerian Agama Kabupaten Aceh Besar</li></ol><p><strong>Sejarah Singkat</strong></p><p class=\"ql-align-justify\">TPQ Ar-Rabwah menjadi cikal bakal tumbuhnya semangat Qurani di lingkungan pesantren. Sejak awal berdirinya, lembaga ini menjadi wadah pembinaan baca-tulis Al-Qur’an dan penanaman akhlak bagi anak-anak dari berbagai daerah.</p><p><strong>Visi</strong></p><p>Menumbuhkan generasi cinta Al-Qur’an, beradab, dan istiqamah dalam ibadah.</p><p><strong>Misi</strong></p><ol><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Mengajarkan baca tulis Al-Qur’an sesuai kaidah tajwid.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Membentuk karakter anak yang berakhlak dan gemar beribadah.</li><li data-list=\"ordered\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Menanamkan nilai keikhlasan, disiplin, dan tanggung jawab sejak dini.</li></ol><p><strong>Tujuan</strong></p><p>Mencetak generasi Qurani yang mampu membaca, menghafal, dan mengamalkan Al-Qur’an dalam kehidupan sehari-hari.</p><p><strong>Keunggulan</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Metode belajar interaktif dan berjenjang</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Pengajar hafizh berpengalaman</li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span>Lingkungan pesantren yang mendukung pembiasaan ibadah</li></ol><p><br></p>','http://rabwah.test/storage/photos/1/swip1.jpg','published',0,0,NULL,NULL,'2025-11-04 15:14:56','2025-11-04 08:14:56','2025-11-04 08:14:56',NULL);
